import java.util.*;
import java.io.*;

public class E {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String s = in.next();
        int len = s.length();

        if (len < 2) {
            System.out.println((s.equals("0") || s.equals("_") || s.equals("X")) ? 1 : 0);
            return;
        }

        if (len == 2) {
            int count = 0;
            for (int i = 10; i <= 95; i += 5) {
                if (i % 25 != 0) continue;
                String str = Integer.toString(i);
                char c1 = s.charAt(0);
                char c2 = s.charAt(1);
                if (Character.isDigit(c1)) {
                    if (Character.isDigit(c2)) {
                        if (s.equals(str)) count++;
                    } else {
                        if (c1 == str.charAt(0)) count++;
                    }
                } else if (c1 == '_') {
                    if (Character.isDigit(c2)) {
                        if (c2 == str.charAt(1)) count++;
                    } else {
                        count++;
                    }
                } else {
                    if (Character.isDigit(c2)) {
                        if (c2 == str.charAt(1)) count++;
                    } else if (c2 == '_') {
                        count++;
                    }
                }
            }
            System.out.println(count);
            return;
        }

        int start = (int) Math.pow(10, len - 1);
        int end = (int) Math.pow(10, len);
        int total = 0;

        for (int num = start; num < end; num += 25) {
            String numStr = Integer.toString(num);
            boolean match = true;
            Set<Character> seen = new HashSet<>();
            for (int j = 0; j < len; j++) {
                char ch = s.charAt(j);
                char digitChar = numStr.charAt(j);
                if (ch == '_') continue;
                if (ch == 'X') {
                    seen.add(digitChar);
                } else if (ch != digitChar) {
                    match = false;
                    break;
                }
            }
            if (match && seen.size() < 2) total++;
        }
        System.out.println(total);
        in.close();
    }
}
